<template>
  <v-container grid-list-xs fluid class="leave-view">
    <!-- Loading Overlay -->
    <v-overlay :value="loading" z-index="1000">
      <v-progress-circular
        color="primary"
        indeterminate
        size="50"
      ></v-progress-circular>
    </v-overlay>

    <!-- Navigation Drawer -->
    <v-navigation-drawer
      app
      class="primary darken-1 white--text"
      clipped
      permanent
      right
      style="z-index: 3;"
    >
      <v-list class="white--text">
        <v-list-item>
          <v-btn class="primary" dark @click="goBack">
            <v-icon light left>mdi-arrow-left</v-icon>
            <span>Go Back</span>
          </v-btn>
        </v-list-item>
      </v-list>
    </v-navigation-drawer>

    <!-- Error State -->
    <v-alert v-if="error && !loading" type="error" outlined prominent class="mt-4">
      {{ error }}
    </v-alert>

    <template v-if="!loading && !error">
      <!-- Summary -->
      <v-card outlined class="summary-card mt-4 mb-4">
        <div class="summary-band" :class="statusMeta.color"></div>
        <v-card-text class="pa-5">
          <div class="d-flex flex-wrap align-center">
            <v-avatar color="primary" size="56" class="mr-4">
              <span class="white--text text-h6 font-weight-bold">{{ initials }}</span>
            </v-avatar>
            <div class="flex-grow-1 summary-who">
              <div class="summary-eyebrow">
                Leave request
              </div>
              <div class="text-h5 font-weight-bold text-truncate">
                {{ practitionerName || "Unknown staff member" }}
              </div>
              <div class="d-flex flex-wrap align-center mt-1">
                <v-chip
                  small
                  label
                  dark
                  :color="getLeaveTypeColor(leaveData.leaveTypeId)"
                  class="mr-3 font-weight-bold"
                >
                  {{ leaveData.leaveCategory || "Leave" }}
                </v-chip>
                <span class="summary-requested">
                  Requested {{ formatDate(leaveData.requestDate) }}
                </span>
              </div>
            </div>
            <v-chip
              :color="statusMeta.color"
              dark
              class="font-weight-bold mt-3 mt-sm-0"
            >
              <v-icon left small>{{ statusMeta.icon }}</v-icon>
              {{ leaveData.statusDisplay || "Unknown status" }}
            </v-chip>
          </div>

          <v-row class="mt-5" dense>
            <v-col v-for="tile in dateTiles" :key="tile.label" cols="6" md="3">
              <div class="stat-tile">
                <div class="stat-label">
                  <v-icon x-small :color="tile.color" class="mr-1">{{ tile.icon }}</v-icon>
                  {{ tile.label }}
                </div>
                <div class="stat-value">{{ tile.value }}</div>
                <div class="stat-sub">{{ tile.sub }}</div>
              </div>
            </v-col>
          </v-row>

          <v-alert
            v-if="leaveData.cancelDate"
            dense
            text
            type="error"
            icon="mdi-cancel"
            class="mt-4 mb-0"
          >
            Cancelled on {{ formatDate(leaveData.cancelDate) }}
          </v-alert>

          <div v-if="leaveData.status === 'recalled'" class="recall-notice mt-4">
            <v-icon color="amber darken-3" class="mr-3">mdi-account-arrow-left</v-icon>
            <div class="recall-notice__body">
              <div class="recall-notice__title">
                Recalled<span v-if="recall.byName"> by {{ recall.byName }}</span>,
                report back on {{ formatDate(recall.date || leaveData.returnDate) }}
              </div>
              <div v-if="recall.originalEndDate" class="recall-notice__meta">
                Originally until {{ formatDate(recall.originalEndDate) }}<span
                  v-if="recall.originalDays !== null && recall.originalDays !== undefined"
                > · {{ recall.originalDays }} days requested, {{ leaveData.days }} taken</span>
              </div>
              <div v-if="recall.reason" class="recall-notice__reason">
                {{ recall.reason }}
              </div>
            </div>
          </div>
        </v-card-text>
      </v-card>

      <v-row>
        <!-- Left: details and study leave -->
        <v-col cols="12" lg="7">
          <v-card outlined class="mb-4">
            <v-card-title class="section-title">
              <v-icon left color="primary">mdi-text-box-outline</v-icon>
              Details
            </v-card-title>
            <v-divider></v-divider>
            <v-card-text class="pa-5">
              <div class="field">
                <div class="field-label">Acting staff while away</div>
                <div class="field-value">
                  <template v-if="actingSupervisorName">
                    <v-icon small color="orange" class="mr-1">mdi-account-switch</v-icon>
                    {{ actingSupervisorName }}
                  </template>
                  <span v-else class="field-empty">Not assigned</span>
                </div>
              </div>

              <div class="field mt-5">
                <div class="field-label">Staff comments</div>
                <div v-if="leaveData.comments" class="comment">
                  {{ leaveData.comments }}
                </div>
                <div v-else class="field-empty">No comments provided</div>
              </div>

              <div v-if="supportingDocuments.length > 0" class="field mt-5">
                <div class="field-label mb-2">Supporting documents</div>
                <div class="d-flex flex-wrap">
                  <v-chip
                    v-for="(doc, index) in supportingDocuments"
                    :key="index"
                    outlined
                    class="mr-2 mb-2"
                    @click="downloadDocument(doc)"
                  >
                    <v-icon left small color="primary">
                      {{ getDocumentIcon(doc.contentType) }}
                    </v-icon>
                    {{ doc.title || `Document ${index + 1}` }}
                    <v-icon right small>mdi-download</v-icon>
                  </v-chip>
                </div>
              </div>
            </v-card-text>
          </v-card>

          <!-- Study Leave Details (if applicable) -->
          <v-card v-if="studyLeaveData" outlined class="mb-4">
            <v-card-title class="section-title">
              <v-icon left color="green darken-1">mdi-school</v-icon>
              Study leave
              <v-spacer></v-spacer>
              <v-chip
                v-if="studyLeaveData.trainingTypeDisplay"
                small
                dark
                :color="getTrainingTypeColor()"
              >
                {{ studyLeaveData.trainingTypeDisplay }}
              </v-chip>
            </v-card-title>
            <v-divider></v-divider>
            <v-tabs
              v-if="trainingSources.length > 1"
              v-model="studyTab"
              grow
              color="green darken-1"
            >
              <v-tab v-for="source in trainingSources" :key="source.key">
                {{ source.title }}
              </v-tab>
            </v-tabs>
            <v-divider v-if="trainingSources.length > 1"></v-divider>
            <v-card-text v-if="activeSource" class="pa-5">
              <div class="d-flex flex-wrap align-center mb-4">
                <div class="text-subtitle-1 font-weight-bold mr-3">
                  {{ activeSource.heading }}
                </div>
                <v-chip
                  v-if="activeSource.status"
                  x-small
                  dark
                  :color="activeSource.status.color"
                >
                  {{ activeSource.status.label }}
                </v-chip>
              </div>
              <div v-if="activeSource.fields.length" class="field-grid">
                <div v-for="f in activeSource.fields" :key="f.label" class="field">
                  <div class="field-label">{{ f.label }}</div>
                  <div class="field-value">
                    <v-icon small color="blue-grey darken-1" class="mr-1">{{ f.icon }}</v-icon>
                    {{ f.value }}
                  </div>
                </div>
              </div>
              <div v-else class="field-empty">No details recorded</div>
              <div v-if="activeSource.description" class="field mt-5">
                <div class="field-label">Description</div>
                <div class="comment">{{ activeSource.description }}</div>
              </div>
            </v-card-text>
          </v-card>
        </v-col>

        <!-- Right: approval progress -->
        <v-col cols="12" lg="5">
          <v-card outlined>
            <v-card-title class="section-title">
              <v-icon left color="primary">mdi-progress-check</v-icon>
              Approval progress
              <v-spacer></v-spacer>
              <span class="step-meta">
                {{ completedSteps }} of {{ approvalSteps.length }} reviewed
              </span>
            </v-card-title>
            <v-divider></v-divider>
            <v-card-text class="pa-5">
              <v-timeline dense align-top class="approval-timeline">
                <v-timeline-item
                  v-for="step in approvalSteps"
                  :key="step.key"
                  :color="step.dotColor"
                  :icon="step.icon"
                  fill-dot
                  small
                >
                  <div class="step" :class="`step--${step.state}`">
                    <div class="d-flex align-center justify-space-between">
                      <span class="step-title">{{ step.title }}</span>
                      <v-chip
                        x-small
                        :color="step.chipColor"
                        :dark="step.chipDark"
                        :outlined="!step.chipDark"
                        class="font-weight-bold"
                      >
                        {{ step.label }}
                      </v-chip>
                    </div>
                    <div
                      v-if="step.approverName || step.date"
                      class="step-meta mt-1"
                    >
                      <span v-if="step.approverName" class="step-approver">
                        <v-icon small color="blue-grey darken-1" class="mr-1">mdi-account</v-icon>{{ step.approverName }}
                      </span>
                      <span v-if="step.approverName && step.date" class="mx-1">·</span>
                      <span v-if="step.date">{{ formatDate(step.date) }}</span>
                    </div>
                    <div v-if="step.comments" class="comment comment--small mt-2">
                      {{ step.comments }}
                    </div>
                    <div v-else-if="step.state === 'current'" class="step-meta mt-1">
                      Waiting for {{ step.who }} to review
                    </div>
                  </div>
                </v-timeline-item>
              </v-timeline>
            </v-card-text>
          </v-card>
        </v-col>
      </v-row>
    </template>
  </v-container>
</template>

<script>
const LEAVE_STATUS = {
  draft: { color: "grey", icon: "mdi-file-document-edit-outline" },
  undersupervisorreview: { color: "orange", icon: "mdi-account-tie" },
  underhodreview: { color: "deep-purple", icon: "mdi-account-star" },
  underhrreview: { color: "blue", icon: "mdi-account-group" },
  underpsreview: { color: "indigo", icon: "mdi-account-key" },
  approved: { color: "success", icon: "mdi-check-circle" },
  cancelled: { color: "blue-grey", icon: "mdi-cancel" },
  recalled: { color: "amber darken-3", icon: "mdi-account-arrow-left" },
};

const STEP_STATES = {
  approved: { label: "Approved", icon: "mdi-check", dotColor: "success", chipColor: "success", chipDark: true },
  rejected: { label: "Rejected", icon: "mdi-close", dotColor: "error", chipColor: "error", chipDark: true },
  current: { label: "In review", icon: "mdi-timer-sand", dotColor: "primary", chipColor: "primary", chipDark: true },
  pending: { label: "Pending", icon: "mdi-circle-small", dotColor: "grey lighten-1", chipColor: "grey", chipDark: false },
  notreached: { label: "Not reached", icon: "mdi-minus", dotColor: "grey lighten-2", chipColor: "grey", chipDark: false },
  notrequired: { label: "Not required", icon: "mdi-minus", dotColor: "grey lighten-2", chipColor: "grey", chipDark: false },
};

const emptyReview = () => ({ status: null, date: "", comments: "", approver: "" });

export default {
  name: "LeaveRequestView",
  props: ["queries"],

  data() {
    return {
      loading: true,
      error: null,

      // Leave request data
      leaveData: {
        leaveCategory: "",
        leaveTypeId: "",
        startDate: "",
        endDate: "",
        returnDate: "",
        requestDate: "",
        cancelDate: "",
        days: 0,
        comments: "",
        status: "",
        statusDisplay: "",
      },

      // Practitioner
      practitionerId: "",
      practitionerName: "",

      // Acting supervisor
      actingSupervisorId: "",
      actingSupervisorName: "",

      // Supporting documents
      supportingDocuments: [],

      // Recall by supervisor (set when status is recalled)
      recall: {
        date: "",
        reason: "",
        originalEndDate: "",
        originalDays: null,
        byId: "",
        byName: "",
      },

      // Study leave data (if applicable)
      studyLeaveData: null,
      studyTab: 0,

      // Reviews; approver is the Person reference of whoever submitted the review
      supervisorReview: emptyReview(),
      hodReview: emptyReview(),
      hrReview: emptyReview(),
      psReview: emptyReview(),

      // Person reference -> display name
      approverNames: {},
    };
  },

  computed: {
    statusMeta() {
      const status = this.leaveData.status;
      if (LEAVE_STATUS[status]) return LEAVE_STATUS[status];
      if (/rejected$/.test(status)) return { color: "error", icon: "mdi-close-circle" };
      return { color: "grey", icon: "mdi-help-circle" };
    },

    initials() {
      const parts = (this.practitionerName || "").split(" ").filter(Boolean);
      if (!parts.length) return "?";
      const first = parts[0][0];
      const last = parts.length > 1 ? parts[parts.length - 1][0] : "";
      return (first + last).toUpperCase();
    },

    dateTiles() {
      const days = Number(this.leaveData.days) || 0;
      return [
        {
          label: "Starts",
          icon: "mdi-calendar-start",
          color: "primary",
          value: this.formatDate(this.leaveData.startDate),
          sub: this.formatWeekday(this.leaveData.startDate),
        },
        {
          label: "Ends",
          icon: "mdi-calendar-end",
          color: "primary",
          value: this.formatDate(this.leaveData.endDate),
          sub: this.formatWeekday(this.leaveData.endDate),
        },
        {
          label: "Back at work",
          icon: "mdi-briefcase-check",
          color: "success",
          value: this.formatDate(this.leaveData.returnDate),
          sub: this.formatWeekday(this.leaveData.returnDate),
        },
        {
          label: "Duration",
          icon: "mdi-timer-outline",
          color: "primary",
          value: `${days} ${days === 1 ? "day" : "days"}`,
          sub: "",
        },
      ];
    },

    approvalSteps() {
      const status = this.leaveData.status;
      const stopped = /rejected$/.test(status) || status === "cancelled";
      const steps = [
        { key: "supervisor", title: "Supervisor", who: "the supervisor", review: this.supervisorReview, underCode: "undersupervisorreview" },
        { key: "hod", title: "Head of Department", who: "the HOD", review: this.hodReview, underCode: "underhodreview" },
        { key: "hr", title: "Human Resources", who: "HR", review: this.hrReview, underCode: "underhrreview" },
      ];
      // no leave route sends requests to the PS today, so the step only appears once a PS review exists
      if (this.psReview.status || status === "underpsreview") {
        steps.push({ key: "ps", title: "Principal Secretary", who: "the PS", review: this.psReview, underCode: "underpsreview" });
      }
      return steps.map((step) => {
        const code = step.review.status?.code;
        let state = "pending";
        if (code === "approved") state = "approved";
        else if (code === "rejected") state = "rejected";
        else if (status === step.underCode) state = "current";
        else if (stopped) state = "notreached";
        else if (status === "approved" || status === "recalled") state = "notrequired";
        return {
          ...step,
          ...STEP_STATES[state],
          state,
          date: step.review.date,
          comments: step.review.comments,
          approverName: this.approverNames[step.review.approver] || "",
        };
      });
    },

    completedSteps() {
      return this.approvalSteps.filter((s) => s.state === "approved" || s.state === "rejected").length;
    },

    trainingSources() {
      const d = this.studyLeaveData;
      if (!d) return [];
      const present = (fields) => fields.filter((f) => f.value || f.value === 0);
      const sources = [
        {
          key: "requested",
          title: "Requested",
          heading: "As requested by staff",
          fields: present([
            { label: "Course / programme", value: d.course, icon: "mdi-book-open-variant" },
            { label: "Institution", value: d.institution, icon: "mdi-domain" },
            { label: "Qualification level", value: d.qualificationLevel, icon: "mdi-certificate" },
            { label: "Country", value: d.country, icon: "mdi-earth" },
            { label: "Location in country", value: d.trainingLocation, icon: "mdi-map-marker" },
          ]),
        },
      ];
      const plan = d.trainingPlan;
      if (plan) {
        sources.push({
          key: "plan",
          title: "Training plan",
          heading: "As planned by staff",
          status: plan.status
            ? { color: this.getPlanStatusColor(plan.status), label: plan.statusDisplay }
            : null,
          fields: present([
            { label: "Course / programme", value: plan.course, icon: "mdi-book-open-variant" },
            { label: "Institution", value: plan.institution, icon: "mdi-domain" },
            { label: "Training type", value: plan.typeDisplay, icon: "mdi-school-outline" },
            { label: "Qualification level", value: plan.qualificationLevel, icon: "mdi-certificate" },
            { label: "Learning methodology", value: plan.methodology, icon: "mdi-human-male-board" },
            { label: "Period", value: this.formatRange(plan.startDate, plan.endDate), icon: "mdi-calendar-range" },
          ]),
        });
      }
      const reco = d.trainingRecommendation;
      if (reco) {
        sources.push({
          key: "recommendation",
          title: "HR recommendation",
          heading: "As recommended by HR",
          description: reco.description,
          fields: present([
            { label: "Training", value: reco.title, icon: "mdi-bullhorn" },
            { label: "Institution", value: reco.institution, icon: "mdi-domain" },
            { label: "Training type", value: reco.typeDisplay, icon: "mdi-school-outline" },
            { label: "Qualification level", value: reco.qualificationLevel, icon: "mdi-certificate" },
            { label: "Learning methodology", value: reco.methodology, icon: "mdi-human-male-board" },
            { label: "Country", value: reco.country, icon: "mdi-earth" },
            { label: "Location in country", value: reco.trainingLocation, icon: "mdi-map-marker" },
            { label: "Period", value: this.formatRange(reco.startDate, reco.endDate), icon: "mdi-calendar-range" },
            { label: "Fiscal year", value: reco.fiscalYear, icon: "mdi-calendar-text" },
            { label: "Total participants", value: reco.totalParticipants, icon: "mdi-account-multiple" },
          ]),
        });
      }
      return sources;
    },

    activeSource() {
      return this.trainingSources[this.studyTab] || this.trainingSources[0] || null;
    },
  },

  async created() {
    if (!this.queries.leave) {
      this.error = "No leave request ID provided";
      this.loading = false;
      return;
    }

    await this.loadLeaveRequest();
  },

  methods: {
    async loadLeaveRequest() {
      this.loading = true;
      this.error = null;

      try {
        // Fetch leave request and all related resources
        const url = `/fhir/Basic?_id=${this.queries.leave}&_revinclude=Basic:leaverequest`;
        const response = await fetch(url);

        if (!response.ok) {
          throw new Error("Failed to load leave request");
        }

        const bundle = await response.json();

        if (!bundle.entry || bundle.entry.length === 0) {
          throw new Error("Leave request not found");
        }

        // Extract resources
        const leaveRequest = bundle.entry.find(
          (e) => e.resource.id === this.queries.leave,
        )?.resource;

        if (!leaveRequest) {
          throw new Error("Leave request not found in response");
        }

        // Extract leave request data
        this.extractLeaveData(leaveRequest);

        // Load related data
        await this.loadPractitioner();
        await this.loadActingSupervisor();
        await this.loadRecalledBy();
        await this.loadLeaveCategory(leaveRequest);

        // Process all included resources for reviews and study leave
        const reviewProfiles = {
          "supervisor-leave-approval-profile": "supervisorReview",
          "hod-leave-approval-profile": "hodReview",
          "hr-leave-approval-profile": "hrReview",
          "ps-leave-approval-profile": "psReview",
        };
        for (const entry of bundle.entry) {
          const resource = entry.resource;
          const profiles = resource.meta?.profile || [];

          for (const [profile, key] of Object.entries(reviewProfiles)) {
            if (profiles.includes(`http://ihris.org/fhir/StructureDefinition/${profile}`)) {
              this[key] = this.extractReview(resource);
            }
          }

          // Check for study leave details
          if (
            profiles.includes(
              "http://ihris.org/fhir/StructureDefinition/study-leave-profile",
            )
          ) {
            await this.extractStudyLeaveData(resource);
          }
        }

        await this.loadApproverNames();
      } catch (error) {
        console.error("Error loading leave request:", error);
        this.error = error.message || "Failed to load leave request";
      } finally {
        this.loading = false;
      }
    },

    extractLeaveData(resource) {
      // match the exact extension name, so original-end-date never stands in for end-date
      const getExt = (name, type) => {
        const ext = resource.extension?.find((e) => e.url.endsWith(`/${name}`));
        return ext ? ext[type] : null;
      };

      this.leaveData.startDate = getExt("start-date", "valueDate");
      this.leaveData.endDate = getExt("end-date", "valueDate");
      this.leaveData.returnDate = getExt("return-date", "valueDate");
      this.leaveData.requestDate = getExt("request-date", "valueDate");
      this.leaveData.cancelDate = getExt("cancel-date", "valueDate");
      this.leaveData.days = getExt("leave-days", "valueInteger") || 0;
      this.leaveData.comments = getExt("comments", "valueString") || "";

      // Recall by supervisor
      this.recall.date = getExt("recall-date", "valueDate") || "";
      this.recall.reason = getExt("recall-reason", "valueString") || "";
      this.recall.originalEndDate = getExt("original-end-date", "valueDate") || "";
      this.recall.originalDays = getExt("original-leave-days", "valueInteger");
      this.recall.byId =
        getExt("recalled-by", "valueReference")?.reference?.split("/")[1] || "";

      // Status
      const statusCoding = getExt("request-status", "valueCoding");
      this.leaveData.status = statusCoding?.code || "";
      this.leaveData.statusDisplay = statusCoding?.display || "";

      // Supporting documents
      const docs = resource.extension?.filter((e) =>
        e.url.includes("supporting-document"),
      );
      this.supportingDocuments = docs?.map((d) => d.valueAttachment) || [];

      // Practitioner ID
      const practExt = resource.extension?.find((e) =>
        e.url.includes("practitioner"),
      );
      this.practitionerId =
        practExt?.valueReference?.reference?.split("/")[1] || "";

      // Acting supervisor ID
      const actingExt = resource.extension?.find((e) =>
        e.url.includes("acting-supervisor"),
      );
      this.actingSupervisorId =
        actingExt?.valueReference?.reference?.split("/")[1] || "";
    },

    async loadPractitioner() {
      if (!this.practitionerId) return;

      try {
        const response = await fetch(
          `/fhir/Practitioner/${this.practitionerId}`,
        );
        const practitioner = await response.json();
        const name = practitioner.name?.[0];
        this.practitionerName = name
          ? `${name.given?.join(" ")} ${name.family}`.trim()
          : "Unknown";
      } catch (error) {
        console.error("Error loading practitioner:", error);
        this.practitionerName = "Unknown";
      }
    },

    async loadActingSupervisor() {
      if (!this.actingSupervisorId) return;

      try {
        const response = await fetch(
          `/fhir/Practitioner/${this.actingSupervisorId}`,
        );
        const supervisor = await response.json();
        const name = supervisor.name?.[0];
        this.actingSupervisorName = name
          ? `${name.given?.join(" ")} ${name.family}`.trim()
          : "Unknown";
      } catch (error) {
        console.error("Error loading acting supervisor:", error);
      }
    },

    async loadRecalledBy() {
      if (!this.recall.byId) return;

      try {
        const response = await fetch(`/fhir/Practitioner/${this.recall.byId}`);
        if (!response.ok) return;
        const practitioner = await response.json();
        const name = practitioner.name?.[0];
        this.recall.byName = name
          ? [...(name.given || []), name.family].filter(Boolean).join(" ")
          : "";
      } catch (error) {
        console.error("Error loading recalling supervisor:", error);
      }
    },

    async loadLeaveCategory(resource) {
      const catExt = resource.extension?.find((e) =>
        e.url.includes("leave-category"),
      );
      const categoryId = catExt?.valueReference?.reference?.split("/")[1];

      if (!categoryId) return;

      try {
        const response = await fetch(`/fhir/Basic/${categoryId}`);
        const category = await response.json();

        this.leaveData.leaveTypeId = categoryId;

        const nameExt = category.extension?.find((e) =>
          e.url.includes("ihris-basic-name"),
        );
        this.leaveData.leaveCategory = nameExt?.valueString || "Unknown";
      } catch (error) {
        console.error("Error loading leave category:", error);
      }
    },

    extractReview(resource) {
      const getExt = (url, type) => {
        const ext = resource.extension?.find((e) => e.url.includes(url));
        return ext ? ext[type] : null;
      };

      return {
        status: getExt("review-status", "valueCoding"),
        date: getExt("action-date", "valueDate"),
        comments: getExt("description", "valueString"),
        approver: getExt("user-reference", "valueReference")?.reference || "",
      };
    },

    async loadApproverNames() {
      const refs = [this.supervisorReview, this.hodReview, this.hrReview, this.psReview]
        .map((review) => review.approver)
        .filter((ref) => ref && ref.startsWith("Person/"));
      const ids = [...new Set(refs.map((ref) => ref.split("/")[1]))];
      if (!ids.length) return;

      // Roles cannot read Person (it holds login details), so go to the Practitioner the
      // user account points at, via the userpractitioner search parameter on Person
      const names = {};
      await Promise.all(
        ids.map(async (id) => {
          try {
            const response = await fetch(
              `/fhir/Practitioner?_has:Person:userpractitioner:_id=${id}&_elements=name`,
            );
            if (!response.ok) return;
            const bundle = await response.json();
            const name = bundle.entry?.[0]?.resource?.name?.[0];
            const display = name
              ? name.text || [...(name.given || []), name.family].filter(Boolean).join(" ")
              : "";
            if (display) names[`Person/${id}`] = display;
          } catch (error) {
            console.error("Error loading approver name:", error);
          }
        }),
      );
      this.approverNames = names;
    },

    async extractStudyLeaveData(resource) {
      const getExt = (url, type) => {
        const ext = resource.extension?.find((e) => e.url.includes(url));
        return ext ? ext[type] : null;
      };

      this.studyLeaveData = {
        institution: getExt("planning-institution", "valueString"),
        course:
          getExt("planning-course", "valueString") ||
          (await this.resolveQualificationName(resource)),
        qualificationLevel: getExt("qualification-level", "valueCoding")
          ?.display,
        country: getExt("country", "valueCoding")?.display,
        trainingLocation: getExt("training-location", "valueString"),
        trainingType: getExt("training-type", "valueCoding")?.code,
        trainingTypeDisplay: getExt("training-type", "valueCoding")?.display,
        trainingPlan: null,
        trainingRecommendation: null,
      };

      // Store references for potential loading
      const planRef = getExt("training-plan-reference", "valueReference");
      const recoRef = getExt(
        "training-recommendation-reference",
        "valueReference",
      );

      if (planRef) {
        this.studyLeaveData.trainingPlan = {
          reference: planRef.reference,
          course: this.studyLeaveData.course,
          institution: this.studyLeaveData.institution,
        };
        await this.loadTrainingPlanDetails(planRef.reference);
      }

      if (recoRef) {
        this.studyLeaveData.trainingRecommendation = {
          reference: recoRef.reference,
          title: this.studyLeaveData.course,
        };
        await this.loadTrainingRecommendationDetails(recoRef.reference);
      }
    },

    async resolveQualificationName(resource) {
      const qualNameOtherExt = resource.extension?.find((e) =>
        e.url.endsWith("/qualification-name-other"),
      );
      if (qualNameOtherExt?.valueString) return qualNameOtherExt.valueString;

      const qualNameExt = resource.extension?.find((e) =>
        e.url.endsWith("/qualification-name"),
      );
      if (qualNameExt?.valueReference?.display) {
        return qualNameExt.valueReference.display;
      }

      const ref = qualNameExt?.valueReference?.reference;
      if (!ref) return null;

      try {
        const id = ref.split("/")[1];
        const response = await fetch(`/fhir/Basic/${id}`);
        if (!response.ok) return null;

        const qualification = await response.json();
        return qualification.extension?.find((e) =>
          e.url.endsWith("/ihris-basic-name"),
        )?.valueString;
      } catch (error) {
        console.error("Error resolving qualification name:", error);
        return null;
      }
    },

    async loadTrainingPlanDetails(reference) {
      try {
        const planId = reference.split("/")[1];
        const response = await fetch(`/fhir/Basic/${planId}`);
        if (!response.ok) return;

        const plan = await response.json();
        const getExt = (url, type) => {
          const ext = plan.extension?.find((e) => e.url.includes(url));
          return ext ? ext[type] : null;
        };

        this.studyLeaveData.trainingPlan = {
          ...this.studyLeaveData.trainingPlan,
          course:
            getExt("planning-course", "valueString") ||
            (await this.resolveQualificationName(plan)) ||
            this.studyLeaveData.trainingPlan.course,
          institution:
            getExt("planning-institution", "valueString") ||
            this.studyLeaveData.trainingPlan.institution,
          typeDisplay: getExt("training-type", "valueCoding")?.display,
          qualificationLevel: getExt("qualification-level", "valueCoding")
            ?.display,
          methodology: getExt("learning-methodology", "valueCoding")?.display,
          startDate: getExt("start-date", "valueDate"),
          endDate: getExt("end-date", "valueDate"),
          status: getExt("request-status", "valueCoding")?.code,
          statusDisplay: getExt("request-status", "valueCoding")?.display,
        };
      } catch (error) {
        console.error("Error loading training plan details:", error);
      }
    },

    async loadTrainingRecommendationDetails(reference) {
      try {
        const recoId = reference.split("/")[1];
        const response = await fetch(`/fhir/Basic/${recoId}`);
        if (!response.ok) return;

        const reco = await response.json();
        const getExt = (url, type) => {
          const ext = reco.extension?.find((e) => e.url.includes(url));
          return ext ? ext[type] : null;
        };

        this.studyLeaveData.trainingRecommendation = {
          ...this.studyLeaveData.trainingRecommendation,
          title:
            getExt("ihris-basic-name", "valueString") ||
            this.studyLeaveData.trainingRecommendation.title,
          description: getExt("description", "valueString"),
          typeDisplay: getExt("training-type", "valueCoding")?.display,
          startDate: getExt("start-date", "valueDate"),
          endDate: getExt("end-date", "valueDate"),
          fiscalYear: getExt("fiscal-year", "valueString"),
          totalParticipants: getExt("total-participants", "valueInteger"),
          institution: getExt("planning-institution", "valueString"),
          qualificationLevel: getExt("qualification-level", "valueCoding")
            ?.display,
          country: getExt("country", "valueCoding")?.display,
          trainingLocation: getExt("training-location", "valueString"),
          methodology: getExt("learning-methodology", "valueCoding")?.display,
        };
      } catch (error) {
        console.error("Error loading training recommendation details:", error);
      }
    },

    getLeaveTypeColor(leaveTypeId) {
      const typeMap = {
        annual: "blue",
        maternity: "pink",
        paternity: "indigo",
        compassionate: "purple",
        unpaid: "orange",
        sick: "red",
        stillborn: "deep-purple",
        bonding: "teal",
        study: "green",
      };
      return typeMap[leaveTypeId] || "grey";
    },

    getTrainingTypeColor() {
      const colorMap = {
        parttime: "blue",
        shortterm: "orange",
        longterm: "purple",
      };
      return colorMap[this.studyLeaveData?.trainingType] || "green";
    },

    getPlanStatusColor(status) {
      const colorMap = {
        draft: "grey",
        undersupervisorreview: "orange",
        approved: "success",
        rejected: "error",
      };
      return colorMap[status] || "grey";
    },

    getDocumentIcon(contentType) {
      if (!contentType) return "mdi-file-document-outline";
      if (contentType.includes("pdf")) return "mdi-file-pdf-box";
      if (contentType.startsWith("image/")) return "mdi-file-image-outline";
      if (contentType.includes("word")) return "mdi-file-word-outline";
      return "mdi-file-document-outline";
    },

    // FHIR dates are plain YYYY-MM-DD; parse as a local date so they never shift a day
    parseDate(dateString) {
      if (!dateString) return null;
      const [year, month, day] = String(dateString)
        .split("T")[0]
        .split("-")
        .map(Number);
      if (!year) return null;
      const date = new Date(year, (month || 1) - 1, day || 1);
      return isNaN(date) ? null : date;
    },

    formatDate(dateString) {
      const date = this.parseDate(dateString);
      if (!date) return "N/A";
      return date.toLocaleDateString("en-GB", {
        day: "numeric",
        month: "short",
        year: "numeric",
      });
    },

    formatWeekday(dateString) {
      const date = this.parseDate(dateString);
      return date ? date.toLocaleDateString("en-GB", { weekday: "long" }) : "";
    },

    formatRange(start, end) {
      if (start && end) return `${this.formatDate(start)} – ${this.formatDate(end)}`;
      if (start) return `From ${this.formatDate(start)}`;
      if (end) return `Until ${this.formatDate(end)}`;
      return "";
    },

    downloadDocument(doc) {
      if (doc.data && doc.contentType) {
        const blob = this.base64toBlob(doc.data, doc.contentType);
        const url = window.URL.createObjectURL(blob);
        const link = document.createElement("a");
        link.href = url;
        link.download = doc.title || "document";
        link.click();
        window.URL.revokeObjectURL(url);
      }
    },

    base64toBlob(base64Data, contentType) {
      contentType = contentType || "";
      const sliceSize = 1024;
      const byteCharacters = atob(base64Data);
      const bytesLength = byteCharacters.length;
      const slicesCount = Math.ceil(bytesLength / sliceSize);
      const byteArrays = new Array(slicesCount);

      for (let sliceIndex = 0; sliceIndex < slicesCount; ++sliceIndex) {
        const begin = sliceIndex * sliceSize;
        const end = Math.min(begin + sliceSize, bytesLength);

        const bytes = new Array(end - begin);
        for (let offset = begin, i = 0; offset < end; ++i, ++offset) {
          bytes[i] = byteCharacters[offset].charCodeAt(0);
        }
        byteArrays[sliceIndex] = new Uint8Array(bytes);
      }
      return new Blob(byteArrays, { type: contentType });
    },

    goBack() {
      if (window.history.length > 1) {
        this.$router.go(-1);
      } else {
        this.$router.push("/");
      }
    },
  },
};
